def max_product(num_str: str, N: int, K: int) -> int:
    """
    Calculate the maximum product by inserting K multiplication signs into the number string.

    Parameters:
    num_str (str): A string representing the number string.
    N (int): An integer representing the length of the number string.
    K (int): An integer representing the number of multiplication signs to insert.

    Returns:
    int: The maximum product that can be obtained by inserting K multiplication signs into the number string.
    """
    if K == 0:
        return int(num_str)
    if K >= N - 1:
        return max(int(digit) for digit in num_str)  # If we have to insert as many signs as possible, return the max digit

    # Edge case: If the number string is all zeros, the maximum product is 0
    if int(num_str) == 0:
        return 0

    # Dynamic programming table to store the maximum product up to index i with j multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, N + 1):
        for j in range(min(i, K + 1)):
            for l in range(i):
                current_number = int(num_str[l:i])
                if j == 0:
                    dp[i][j] = max(dp[i][j], current_number)
                else:
                    dp[i][j] = max(dp[i][j], dp[l][j - 1] * current_number)

    return dp[N][K]

