def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn_parts):
        total = sum((10 - i) * int(part) for i, part in enumerate(isbn_parts[:9]))
        remainder = total % 11
        checksum = 11 - remainder
        return 'X' if checksum == 10 else str(checksum % 11)

    isbn_parts = isbn.replace('-', '')
    if len(isbn_parts) != 10 or not isbn_parts[:-1].isdigit():
        raise ValueError("Invalid ISBN format")

    calculated_checksum = calculate_checksum(isbn_parts)
    provided_checksum = isbn_parts[-1]

    if calculated_checksum == provided_checksum:
        return "Right"
    else:
        corrected_isbn = isbn[:-1] + calculated_checksum
        return corrected_isbn

def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        # Remove dashes and prepare for checksum calculation
        cleaned_isbn = isbn.replace('-', '')
        total = 0
        for i in range(9):
            total += int(cleaned_isbn[i]) * (10 - i)
        checksum = 11 - (total % 11)
        if checksum == 10:
            return 'X'
        elif checksum == 11:
            return '0'
        else:
            return str(checksum)

    # Extract the provided checksum
    provided_checksum = isbn[-1]
    # Calculate the correct checksum
    calculated_checksum = calculate_checksum(isbn)

    if provided_checksum == calculated_checksum:
        return "Right"
    else:
        # Replace the incorrect checksum with the correct one
        corrected_isbn = isbn[:-1] + calculated_checksum
        return corrected_isbn

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Initialize counts for horizontal and vertical aisles
    horizontal_aisle_counts = [0] * (M + 1)
    vertical_aisle_counts = [0] * (N + 1)

    # Count the number of chatting pairs that can be separated by each possible aisle
    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Xi == Pi:  # Same row, need vertical aisle
            if Yi < Qi:
                vertical_aisle_counts[Yi] += 1
            else:
                vertical_aisle_counts[Qi] += 1
        elif Yi == Qi:  # Same column, need horizontal aisle
            if Xi < Pi:
                horizontal_aisle_counts[Xi] += 1
            else:
                horizontal_aisle_counts[Pi] += 1

    # Find the K most effective rows for horizontal aisles
    horizontal_aisle_indices = sorted(range(1, M + 1), key=lambda x: horizontal_aisle_counts[x], reverse=True)[:K]
    horizontal_aisle_indices_str = ' '.join(map(str, sorted(horizontal_aisle_indices)))

    # Find the L most effective columns for vertical aisles
    vertical_aisle_indices = sorted(range(1, N + 1), key=lambda x: vertical_aisle_counts[x], reverse=True)[:L]
    vertical_aisle_indices_str = ' '.join(map(str, sorted(vertical_aisle_indices)))

    return (horizontal_aisle_indices_str, vertical_aisle_indices_str)

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    row_counts = [0] * (M + 1)
    col_counts = [0] * (N + 1)

    for pair in chatting_pairs:
        X1, Y1, X2, Y2 = pair
        if X1 == X2:
            # They are in the same row, consider vertical aisles
            if Y1 < Y2:
                col_counts[Y2] += 1
            else:
                col_counts[Y1] += 1
        elif Y1 == Y2:
            # They are in the same column, consider horizontal aisles
            if X1 < X2:
                row_counts[X2] += 1
            else:
                row_counts[X1] += 1

    # Sort the row and column counts in descending order
    sorted_rows = sorted(range(1, M + 1), key=lambda x: row_counts[x], reverse=True)
    sorted_cols = sorted(range(1, N + 1), key=lambda x: col_counts[x], reverse=True)

    # Select the top K row indices and L column indices
    optimal_rows = sorted_rows[:K]
    optimal_cols = sorted_cols[:L]

    # Convert to space-separated strings
    row_str = ' '.join(map(str, optimal_rows))
    col_str = ' '.join(map(str, optimal_cols))

