    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    for participant, stmts in statements.items():
        for stmt in stmts:
            # Ignore statements about the day of the week
            if any(day in stmt for day in days_of_week):
                continue

            # Check statements about guilt and non-guilt
            if f"{scenario} is guilty." in stmt:
                # If the participant says the scenario is guilty
                if participant not in liar_count:
                    # If the participant is not a liar, the scenario must be the criminal
                    if participant != scenario:
                        return False
            elif f"{scenario} is not guilty." in stmt:
                # If the participant says the scenario is not guilty
                if participant not in liar_count:
                    # If the participant is not a liar, the scenario cannot be the criminal
                    if participant == scenario:
                        return False
    return True

