def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if c.islower():
            return chr((ord(c) - ord(k) - 97) % 26 + 97)
        else:
            return chr((ord(c) - ord(k) - 65) % 26 + 65)

    # Validate inputs
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must consist only of alphabetic characters.")

    key = key.upper()
    ciphertext = ciphertext.upper()
    key_length = len(key)
    decrypted_text = []

    for i, c in enumerate(ciphertext):
        k = key[i % key_length]
        decrypted_text.append(shift_char(c, k))

    return ''.join(decrypted_text).lower()

