def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.

    Args:
    heights (List[int]): A list of student heights.

    Returns:
    int: The minimum number of students that need to leave.
    """
    if not heights:
        return 0

    n = len(heights)
    left = [1] * n
    right = [1] * n

    # Calculate the longest increasing subsequence from the left
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                left[i] = max(left[i], left[j] + 1)

    # Calculate the longest increasing subsequence from the right
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j]:
                right[i] = max(right[i], right[j] + 1)

    # Calculate the minimum students to leave
    min_leave = n
    for i in range(n):
        # left[i] + right[i] - 1 because the student at position i is counted twice
        min_leave = min(min_leave, n - (left[i] + right[i] - 1))

    return min_leave

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("Number of disc pairs must be at least 1.")

    # Base cases
    if n == 1:
        return 2
    if n == 2:
        return 6

    # Initialize the number of moves for 1 and 2 pairs
    moves = [0, 2, 6]

    # Iteratively compute the number of moves for n pairs using the relation:
    # M(n) = 3 * M(n-1) - M(n-2) + 2
    for i in range(3, n + 1):
        next_moves = 3 * moves[-1] - moves[-2] + 2
        moves.append(next_moves)

    return moves[n]
